#include "cyclic-lease-ring.h"
#include <stdexcept>
namespace lease_ring {Ring::Ring(std::size_t n):slots_(n){}std::optional<Lease> Ring::acquire(std::uint64_t epoch){if(last_epoch_&&epoch<*last_epoch_)throw std::invalid_argument("epoch");last_epoch_=epoch;if(slots_.empty()||active_==slots_.size())return std::nullopt;for(std::size_t n=0;n<slots_.size();++n){auto i=(cursor_+n)%slots_.size();if(!slots_[i].active){auto& s=slots_[i];s.active=true;s.epoch=epoch;++s.generation;++active_;cursor_=(i+1)%slots_.size();return Lease{i,s.generation};}}return std::nullopt;}std::size_t Ring::retire_through(std::uint64_t epoch){std::size_t n=0;for(auto& s:slots_)if(s.active&&s.epoch<=epoch){s.active=false;--active_;++n;}cursor_=0;return n;}std::size_t Ring::active()const noexcept{return active_;}}
